#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/home/hao/Documents/AI/Course}"
LAB4="$ROOT/Lab/Lab4"
RAG="$LAB4/rag_pipeline"
APP="$RAG/app.py"
REL="$RAG/relevance.py"
REQ="$RAG/requirements.txt"
ENV_FILE="$LAB4/.env"
TEST_REL="$RAG/tests/test_relevance.py"
TEST_E2E="$LAB4/test_anti_hallucination.py"

for item in "$APP" "$REL" "$REQ" "$ENV_FILE" "$LAB4/docker-compose.yml"; do
  if [[ ! -f "$item" ]]; then
    echo "ERROR: Không tìm thấy $item" >&2
    exit 1
  fi
done

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$LAB4/backups/final_grounding_$STAMP"
mkdir -p "$BACKUP"
cp "$APP" "$REL" "$REQ" "$ENV_FILE" "$LAB4/docker-compose.yml" "$BACKUP/"
[[ -f "$TEST_REL" ]] && cp "$TEST_REL" "$BACKUP/"
[[ -f "$TEST_E2E" ]] && cp "$TEST_E2E" "$BACKUP/"

echo "[1/6] Ghi bản sửa grounding đã kiểm tra cú pháp..."

printf '%s' '' | base64 -d > "$APP"
printf '%s' '' | base64 -d > "$REL"

mkdir -p "$RAG/tests"
touch "$RAG/tests/__init__.py"
printf '%s' '' | base64 -d > "$TEST_REL"
printf '%s' '' | base64 -d > "$TEST_E2E"

if ! grep -Eq '^stopwordsiso([<>=]|$)' "$REQ"; then
  printf '\nstopwordsiso>=0.6,<1\n' >> "$REQ"
fi

echo "[2/6] Cập nhật ngưỡng retrieval..."

python3 - "$ENV_FILE" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
updates = {
    "TOP_K": "5",
    "LOW_CONFIDENCE_THRESHOLD": "0.60",
    "HIGH_CONFIDENCE_THRESHOLD": "0.72",
    "MIN_KEYWORD_OVERLAP": "1",
    "MIN_KEYWORD_COVERAGE": "0.20",
    "MAX_CONTEXT_CHUNKS": "2",
}

lines = path.read_text(encoding="utf-8").splitlines()
output = []
seen = set()

for line in lines:
    if "=" in line and not line.lstrip().startswith("#"):
        key = line.split("=", 1)[0].strip()
        if key in updates:
            output.append(f"{key}={updates[key]}")
            seen.add(key)
            continue
    output.append(line)

for key, value in updates.items():
    if key not in seen:
        output.append(f"{key}={value}")

path.write_text("\n".join(output).rstrip() + "\n", encoding="utf-8")
PY

echo "[3/6] Xóa cache Python và kiểm tra cú pháp..."

find "$RAG" -type d -name '__pycache__' -prune -exec rm -rf {} +
python3 -m py_compile "$APP" "$REL" "$TEST_REL" "$TEST_E2E"

echo "[4/6] Rebuild rag-app..."

cd "$LAB4"
docker compose up -d --build rag-app

RAG_PORT="$(awk -F= '$1 == "RAG_PORT" {print $2}' .env | tail -n 1)"
RAG_PORT="${RAG_PORT:-8001}"
BASE_URL="http://localhost:$RAG_PORT"

echo "Đợi API healthy tại $BASE_URL..."
ready=0
for _ in $(seq 1 90); do
  if curl -fsS "$BASE_URL/health" >/dev/null 2>&1; then
    ready=1
    break
  fi
  sleep 2
done

if [[ "$ready" -ne 1 ]]; then
  echo "ERROR: API chưa healthy." >&2
  docker compose ps
  docker compose logs --tail=200 rag-app
  exit 1
fi

echo "[5/6] Chạy unit test..."
docker compose exec -T rag-app python -m unittest -v tests.test_relevance

echo "[6/6] Chạy regression test end-to-end..."
RAG_BASE_URL="$BASE_URL" python3 "$TEST_E2E"

echo
echo "=============================================="
echo "PASS: Đã chặn câu ngoài phạm vi."
echo "UI: $BASE_URL"
echo "Backup: $BACKUP"
echo "=============================================="
